--        (checklist.md बमोजिम ३४ चरण, १४२ बुँदा)
--
-- यो migration ले पुरानो १२-चरण/५५-बुँदे checklist लाई हटाई नयाँ
-- ३४-चरण/१४२-बुँदे checklist राख्छ र पुराना inspection results,
-- evidence reference तथा findings लाई checklist_code आधारमा नयाँ
-- बुँदासँग जोडी सुरक्षित रूपमा राख्छ (data-preserving)।
-- ====================================================================
BEGIN;

-- 1) पुरानो checklist_code → नयाँ checklist_code को mapping
CREATE TEMP TABLE _chk_code_map (
    old_code VARCHAR(50) PRIMARY KEY,
    new_code VARCHAR(50) NOT NULL
) ON COMMIT DROP;

