-- 2) पुराना links को snapshot (पुरानो checklist_items id सहित)
CREATE TEMP TABLE _chk_result_snap (
    old_result_id INTEGER PRIMARY KEY,
    inspection_id INTEGER,
    new_code VARCHAR(50),
    compliance_status VARCHAR(50),
    risk_level VARCHAR(50),
    evidence_reference TEXT,
    observation TEXT,
    financial_impact NUMERIC(15, 2),
    inspector_comment TEXT,
    completed_by INTEGER,
    completed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE,
    updated_at TIMESTAMP WITH TIME ZONE
) ON COMMIT DROP;

INSERT INTO _chk_result_snap
SELECT r.id, r.inspection_id, m.new_code, r.compliance_status, r.risk_level,
       r.evidence_reference, r.observation, r.financial_impact, r.inspector_comment,
       r.completed_by, r.completed_at, r.created_at, r.updated_at
FROM inspection_checklist_results r
JOIN checklist_items ci ON ci.id = r.checklist_item_id
JOIN _chk_code_map m ON m.old_code = ci.checklist_code;

CREATE TEMP TABLE _chk_finding_snap (
    finding_id INTEGER PRIMARY KEY,
    inspection_id INTEGER,
    new_code VARCHAR(50)
) ON COMMIT DROP;

INSERT INTO _chk_finding_snap (finding_id, inspection_id, new_code)
SELECT f.id, f.inspection_id, m.new_code
FROM findings f
JOIN checklist_items ci ON ci.id = f.checklist_item_id
JOIN _chk_code_map m ON m.old_code = ci.checklist_code;

CREATE TEMP TABLE _chk_evidence_snap (
    evidence_id INTEGER PRIMARY KEY,
    new_code VARCHAR(50)
) ON COMMIT DROP;

INSERT INTO _chk_evidence_snap (evidence_id, new_code)
SELECT e.id, m.new_code
FROM evidence_files e
JOIN checklist_items ci ON ci.id = e.checklist_item_id
JOIN _chk_code_map m ON m.old_code = ci.checklist_code;

-- 3) पुरानो checklist हटाउने (links FK SET NULL/CASCADE द्वारा खाली हुन्छन्)
DELETE FROM inspection_checklist_results;
DELETE FROM checklist_items;
DELETE FROM checklist_stages;

