(3, 'PROC-003', 1, 1, 'बजार तथा विगत खरिद अध्ययन (Market Study)', 'नियम ३', 'बजार अध्ययन प्रतिवेदन, विगत खरिद विवरण, आपूर्तिकर्ता विवरण', 'बजारमा उपलब्ध आपूर्तिकर्ता/निर्माण व्यवसायी/सेवा प्रदायकको अवस्था र विगतमा भएको समान खरिदको अध्ययन गरिएको छ?', 'बजार अध्ययन नगरी अनुमानित मूल्य र परिमाण हचुवाका भरमा निर्धारण गर्ने', 'न्यून', 3),
(4, 'PROC-004', 1, 1, 'विवरण, परिमाण र आर्थिक स्रोत (Scope & Source)', 'नियम ३', 'विस्तृत विवरण/परिमाण तालिका, आर्थिक स्रोत पहिचान टिप्पणी', 'खरिद गरिने वस्तु/कार्य/सेवाको विवरण र परिमाण यकिन गरी आर्थिक स्रोत पहिचान गरिएको छ?', 'परिमाण बढाएर/घटाएर आवश्यकताभन्दा फरक खरिद सिर्जना गर्ने', 'मध्यम', 4),
(5, 'PROC-005', 1, 1, 'सम्भाव्यता अध्ययन (Design & Build/EPC)', 'नियम ३', 'सम्भाव्यता अध्ययन प्रतिवेदन, Conceptual Design, स्वीकृति निर्णय', 'Design & Build वा EPC खरिद भए आर्थिक, सामाजिक, प्राविधिक तथा वातावरणीय सम्भाव्यता अध्ययन र Conceptual Design तयार गरिएको छ?', 'सम्भाव्यता अध्ययन नगरी जटिल आयोजना अघि बढाई जोखिम र थप लागत सिर्जना गर्ने', 'उच्च', 5),
(6, 'PROC-006', 2, 2, 'लिखित आदेश र खरिद माग स्वीकृति (Demand Approval)', 'नियम ३', 'अधिकार प्राप्त अधिकारीको लिखित आदेश, स्वीकृत खरिद माग फाराम', 'अधिकार प्राप्त अधिकारीको लिखित आदेश प्राप्त गरी सम्बन्धित महाशाखा/शाखाबाट खरिद माग प्राप्त र स्वीकृत गराइएको छ?', 'मौखिक आदेश वा स्वीकृति विना खरिद प्रक्रिया सुरु गर्ने', 'मध्यम', 6),
(7, 'PROC-007', 2, 2, 'खरिद माग विवरण पूर्णता (Demand Completeness)', 'नियम ३', 'खरिद माग फाराम, गुणस्तर/परिमाण विवरण, स्रोत खुलाइएको टिप्पणी', 'खरिद मागमा विवरण, गुणस्तर, परिमाण, आवश्यक समय, अनुमानित मूल्य र रकम व्यहोर्ने स्रोत खुलाइएको छ?', 'अपूर्ण मागका आधारमा पछि स्पेसिफिकेसन परिवर्तन/भेरिएसनको बाटो खोल्ने', 'मध्यम', 7),
(8, 'PROC-008', 2, 2, 'प्याकेज विभाजन (Packaging/Lotting)', 'नियम ४', 'प्याकेजिङ औचित्य टिप्पणी, खरिद गुरुयोजनासँग भिडान अभिलेख', 'खरिदलाई उपयुक्त समूह/प्याकेजमा विभाजन गरी खरिद गुरुयोजनासँग मिल्ने गरी प्याकेज निर्धारण गरिएको छ?', 'गुरुयोजना विपरित प्याकेज बनाई स्रोत बाँडफाँट र प्रतिस्पर्धामा असर पार्ने', 'मध्यम', 8),
(9, 'PROC-009', 2, 2, 'स्वतन्त्र कामको छुट्टाछुट्टै बोलपत्र (Independent Works)', 'नियम ४', 'खण्डीकरण योजना, बोलपत्र आह्वान सम्बन्धी निर्णय', 'अलग-अलग सम्पन्न गर्न सकिने निर्माण कार्यमा अधिकतम प्रतिस्पर्धा हुने गरी छुट्टाछुट्टै बोलपत्र आह्वान गरिएको छ?', 'एउटै आह्वानमा स्वतन्त्र काम जोडी ठूला निर्माण व्यवसायीलाई मात्र योग्य बनाउने', 'न्यून', 9),
(10, 'PROC-010', 2, 2, 'टुक्रेकरण/कृत्रिम प्याकेज नियन्त्रण (Anti-Splitting)', 'ऐन दफा ३(२) / नियम ४', 'लागत अनुमान र प्याकेजिङ तुलना, सीमा विश्लेषण टिप्पणी', 'प्रतिस्पर्धा सीमित हुने गरी टुक्रा-टुक्रा पारी वा कृत्रिम रूपमा ठूलो प्याकेज बनाई खरिद गरिएको छैन?', 'खरिद विधि/सीमा छल्न जानाजान टुक्रेकरण गर्ने वा एउटै कामलाई कृत्रिम रूपमा ठूलो बनाउने', 'उच्च', 10),
(11, 'PROC-011', 3, 3, 'Specification/Design/TOR तयारी (Technical Documents)', 'ऐन दफा ४(१) / नियम ४', 'मालसामानको स्पेसिफिकेसन, योजना/नक्सा/Design, परामर्श सेवाको TOR', 'मालसामानको Specification, निर्माण कार्यको योजना/नक्सा/Design र परामर्श सेवाको TOR तयार गरिएको छ?', 'स्पेसिफिकेसन विना वा अपुरो स्पेसिफिकेसनका आधारमा खरिद अघि बढाउने', 'उच्च', 11),
(12, 'PROC-012', 3, 3, 'वस्तुगत Specification (Objective Specification)', 'ऐन दफा ४(२)', 'वस्तुगत प्राविधिक/गुणस्तर मापदण्ड सहितको स्पेसिफिकेसन', 'Specification वस्तुगत प्राविधिक तथा गुणस्तरका आधारमा तयार गरिएको छ?', 'गुणस्तरमा सम्झौता गरी न्यूनस्तरको सामग्री खरिदको बाटो खोल्ने', 'मध्यम', 12),
(13, 'PROC-013', 3, 3, 'ब्रान्ड/उत्पादक उल्लेख निषेध (Brand Neutrality)', 'ऐन दफा ४(३)', 'स्पेसिफिकेसन समीक्षा टिप्पणी, "वा सो सरह" व्यवस्था उल्लेख', 'अनावश्यक रूपमा खास Brand, Trademark, Patent, Design, Origin वा Manufacturer नतोकी आवश्यक परे "वा सो सरह" व्यवस्था गरिएको छ?', 'निश्चित ब्रान्ड/उत्पादक तोकी प्रतिस्पर्धा संकुचित गर्ने', 'अत्यन्त उच्च', 13),
(14, 'PROC-014', 3, 3, 'Testing/Marking/Packaging/Conformity (Quality Requirement)', 'ऐन दफा ४(४) / नियम ४', 'परीक्षण/चिन्हांकन/प्याकेजिङ/लेबलिङ मापदण्ड, विशेष आवश्यकता विवरण', 'Testing, Marking, Packaging, Labelling तथा Conformity सम्बन्धी आवश्यकता र विशेष आवश्यकता भएको विवरण निर्धारण गरिएको छ?', 'परीक्षण सम्बन्धी शर्त नराखी न्यून गुणस्तरको मालसामान स्वीकार्ने बाटो खोल्ने', 'मध्यम', 14),
(15, 'PROC-015', 3, 3, 'Specification/Design स्वीकृति (Technical Approval)', 'नियम ४', 'स्वीकृत टिप्पणी/निर्णय, प्राविधिक स्वीकृति पत्र', 'सम्बन्धित अधिकारीबाट Specification/Design/Plan/TOR स्वीकृत गराइएको छ र जटिल संरचनामा विभागीय प्रमुखबाट स्वीकृत गराइएको छ?', 'स्वीकृति विना स्पेसिफिकेसन प्रयोग गरी पछि जिम्मेवारीबाट पन्छिने', 'मध्यम', 15),
(16, 'PROC-016', 3, 3, 'संशोधन नियमबमोजिम (Revision Control)', 'नियम ४', 'संशोधन औचित्य टिप्पणी, पुनःस्वीकृति निर्णय', 'स्वीकृत Specification/Design मा संशोधन आवश्यक भए नियमबमोजिम मात्र संशोधन गरिएको छ?', 'स्वीकृत मापदण्ड मनलाग्दी परिवर्तन गरी निश्चित आपूर्तिकर्तालाई लाभ पुर्याउने', 'उच्च', 16),
(17, 'PROC-017', 4, 4, 'लागत अनुमान तयारी (Cost Estimate)', 'ऐन दफा ५ / नियम ८', 'लागत अनुमान फाइल, सम्झौता/विकल्प अध्ययन टिप्पणी', 'लागत अनुमान तयार गरी एउटै वा अलग-अलग सम्झौताबाट गर्ने यकिन र नवीकरण/वैकल्पिक खरिद विकल्पको अध्ययन गरिएको छ?', 'विकल्प अध्ययन नगरी महँगो खरिद विकल्प रोज्ने', 'मध्यम', 17),
(18, 'PROC-018', 4, 4, 'सम्भावित अधिकतम लागत समावेश (Maximum Cost Inclusion)', 'नियम ८', 'लागत अनुमान विवरण, जमानत/बीमा/परीक्षण खर्च गणना', 'Bid/Performance Security, Mobilization/Demobilization, बीमा, गुणस्तर परीक्षण, Occupational Health & Safety, As-built Drawing आदि खर्च सम्भावित अधिकतम लागतसहित लागत अनुमानमा समावेश गरिएको छ?', 'आवश्यक खर्च नराखी कम लागत देखाई पछि थप रकम माग्ने', 'मध्यम', 18),
(19, 'PROC-019', 4, 4, 'निर्माण कार्यको Technical Check (Technical Check of Estimate)', 'नियम ९', 'स्वीकृत Norms, दररेट निर्धारण समितिको दर, Technical Check प्रतिवेदन', 'निर्माण कार्यको लागत अनुमानमा स्वीकृत Norms, सामग्रीको बजार दर र दररेट निर्धारण समितिको दर प्रयोग गरी Technical Check गराइएको छ?', 'मनपरी दर राखी लागत अनुमान बढाउने वा न्यून देखाई पछि भेरिएसन गर्ने', 'उच्च', 19),
(20, 'PROC-020', 4, 4, 'मालसामान/सेवाको लागत अनुमान (Goods/Services Estimate)', 'नियम ९', 'विगत खरिद लागत विवरण, बजार मूल्य, उद्योग वाणिज्य संघको दररेट, जनशक्ति/भ्रमण खर्च', 'मालसामान/परामर्श/अन्य सेवाको लागत अनुमानमा विगतको वास्तविक लागत, बजार मूल्य, दररेट र जनशक्ति/भ्रमण/कार्यालय/प्रतिवेदन खर्च समावेश गरिएको छ?', 'तथ्यहीन आधारमा लागत अनुमान तयार गरी अनुमानित रकम बढाउने', 'मध्यम', 20),
(21, 'PROC-021', 4, 4, 'अनुसूची ढाँचा र अद्यावधिक (Estimate Format)', 'ऐन दफा ५(२) / नियम ९', 'निर्धारित अनुसूची ढाँचाको लागत अनुमान, अद्यावधिक अभिलेख', 'निर्धारित अनुसूचीको ढाँचामा लागत अनुमान तयार गरी अद्यावधिक राखिएको छ?', 'पुरानो दरको लागत अनुमान प्रयोग गरी खरिद आह्वान गर्ने', 'न्यून', 21),
(22, 'PROC-022', 4, 4, 'लागत अनुमान स्वीकृति (Estimate Approval)', 'ऐन दफा ५क / नियम १४', 'अधिकार प्राप्त अधिकारीको स्वीकृति, अख्तियारी तह निर्धारण टिप्पणी', 'Specification/Design र लागत अनुमान अधिकार प्राप्त अधिकारीबाट स्वीकृत गराई अख्तियारी क्षेत्रअनुसार स्वीकृतिको तह निर्धारण गरिएको छ?', 'अधिकार क्षेत्र नाघेर वा विना स्वीकृति लागत अनुमान प्रयोग गर्ने', 'उच्च', 22),
(23, 'PROC-023', 4, 4, 'वार्षिक अद्यावधिक (Annual Updating)', 'नियम १४', 'अद्यावधिक लागत अनुमान, पुनःस्वीकृति निर्णय', 'खरिद हुन नसकेमा प्रत्येक आर्थिक वर्ष लागत अनुमान अद्यावधिक गरी मात्र RFQ/Bid/RFP आह्वान गरिएको छ?', 'अद्यावधिक नगरी पुरानै लागत अनुमानका आधारमा आह्वान गर्ने', 'मध्यम', 23),
(24, 'PROC-024', 5, 5, 'बजेट सुनिश्चितता (Budget Assurance)', 'नियम ५', 'बजेट विनियोजन पत्र, बहुवर्षीय स्रोत सुनिश्चितता कागजात', 'खरिदका लागि आवश्यक बजेट सुनिश्चित गरिएको छ र बहुवर्षीय खरिद भए पहिलो तथा आगामी वर्षहरूको बजेट सुनिश्चित गरिएको छ?', 'बजेट सुनिश्चितता विना खरिद प्रक्रिया अघि बढाई दायित्व थुपार्ने', 'अत्यन्त उच्च', 24),
(25, 'PROC-025', 5, 5, 'निर्माणस्थल उपलब्धता (Site Availability)', 'नियम ५', 'साइट उपलब्धता कागजात, मुआब्जा/क्षतिपूर्ति सुनिश्चितता, वातावरणीय स्वीकृति', 'निर्माणस्थल उपलब्ध गराई हटाउनुपर्ने संरचना/रुख व्यवस्थापन, मुआब्जा बजेट र आवश्यक वातावरणीय अध्ययन स्वीकृत भएको सुनिश्चित गरिएको छ?', 'साइट विवाद र मुआब्जा टुङ्गो नलगाई काम सुरु गराई म्याद थपको बाटो खोल्ने', 'उच्च', 25),
(26, 'PROC-026', 5, 5, 'आधारभूत तयारी पूर्णता (Readiness before Invitation)', 'नियम ५', 'तयारी पूर्णता जाँच टिप्पणी, बजेट/साइट/वातावरणीय कागजात', 'बजेट, निर्माणस्थल र वातावरणीय स्वीकृति पूरा भएपछि मात्र बोलपत्र आह्वान गरिएको छ?', 'आधारभूत तयारी नपुगी आह्वान गरी खरिद प्रक्रिया असफल बनाउने', 'उच्च', 26),
(27, 'PROC-027', 6, 6, 'खरिद गुरुयोजना आवश्यकता (Master Plan Requirement)', 'ऐन दफा ६ / नियम ६', 'गुरुयोजना आवश्यकता निर्धारण टिप्पणी, आयोजना अवधि/रकम विवरण', 'एक वर्षभन्दा बढी अवधिको आयोजना वा वार्षिक रु. १० करोडभन्दा बढी खरिदका लागि खरिद गुरुयोजना तयार गरिएको छ?', 'गुरुयोजना बनाउनुपर्ने खरिदमा नबनाई टुक्रेकरण गर्ने', 'उच्च', 27),
(28, 'PROC-028', 6, 6, 'गुरुयोजनाको विषयवस्तु (Master Plan Content)', 'नियम ६', 'प्रकार/परिमाण/लागत/विधि/प्याकेजिङ/समयतालिका सहितको गुरुयोजना', 'गुरुयोजनामा खरिद प्रकार, परिमाण, मोटामोटी लागत, खरिद विधि, प्याकेजिङ, सम्झौता संख्या, पूर्वयोग्यता र समयतालिका समावेश गरिएको छ?', 'अधुरो गुरुयोजना बनाई वार्षिक योजनासँग बाझिने खरिद गर्ने', 'न्यून', 28),
(29, 'PROC-029', 6, 6, 'गुरुयोजना स्वीकृति/अद्यावधिक (Approval & Update)', 'नियम ६', 'स्वीकृत गुरुयोजना, वार्षिक अद्यावधिक अभिलेख', 'गुरुयोजना स्वीकृत गराई प्रत्येक आर्थिक वर्ष अद्यावधिक गरिएको छ?', 'स्वीकृति विना गुरुयोजनाका आधारमा खरिद गर्ने', 'न्यून', 29),
(30, 'PROC-030', 6, 6, 'वार्षिक खरिद योजना आवश्यकता (Annual Plan Requirement)', 'ऐन दफा ६ / नियम ७', 'वार्षिक खरिद योजना, स्वीकृति टिप्पणी', 'वार्षिक रु. १० लाखभन्दा बढीको खरिदका लागि वार्षिक खरिद योजना तयार गरी गुरुयोजना भए त्यसलाई आधार बनाइएको छ?', 'वार्षिक योजना बाहिर राखी मनलाग्दी खरिद गर्ने', 'उच्च', 30),
(31, 'PROC-031', 6, 6, 'वार्षिक योजनाको विषयवस्तु (Annual Plan Content)', 'नियम ७', 'समयतालिका सहितको वार्षिक योजना (Specification देखि कार्य सम्पन्न मितिसम्म)', 'वार्षिक योजनामा खरिद प्रकार, सम्भावित प्याकेज, विधि र Specification, लागत अनुमान, Bid/RFQ/EOI/RFP कागजात, सूचना प्रकाशन, मूल्याङ्कन, स्वीकृति, सम्झौता, कार्य सुरु/सम्पन्न मिति उल्लेख गरिएको छ?', 'समयतालिका नराखी योजना बनाउने र खरिद वर्षभरि तानातानी गर्ने', 'न्यून', 31),
(32, 'PROC-032', 6, 6, 'योजना पठाउने/परिमार्जन/अनुगमन (Plan Communication)', 'नियम ७', 'पठाइएको योजना, परिमार्जित योजना, अनुगमन प्रतिवेदन', 'वार्षिक खरिद योजना सम्बन्धित निकायमा पठाई स्वीकृत बजेटपछि परिमार्जन/स्वीकृत गरी पुनः पठाइएको छ र तालुक कार्यालयबाट समयमै खरिद भए/नभएको अनुगमन गरिएको छ?', 'योजना अद्यावधिक र पठन नगरी तालुक निकायलाई जानकारी नगराउने', 'न्यून', 32),
(33, 'PROC-033', 7, 7, 'खरिद अधिकारी तोक्ने (Designation of Procurement Officer)', 'ऐन दफा ७, ७(२)(३) / नियम ११', 'खरिद अधिकारी तोकिएको निर्णय, योग्यता/तालिम कागजात', 'योग्य/तालिमप्राप्त कर्मचारी तोकी आवश्यकता अनुसार छुट्टै खरिद महाशाखा/शाखा/इकाइ स्थापना गरी खरिद अधिकारी तोकिएको छ?', 'अयोग्य/तालिम नपाएको व्यक्तिलाई खरिद अधिकारी बनाई प्रक्रियामा त्रुटि गर्ने', 'मध्यम', 33),
(34, 'PROC-034', 7, 7, 'मौजुदा सूची (Standing List)', 'ऐन दफा ६क / नियम १३', 'मौजुदा सूची (Standing List), अद्यावधिक अभिलेख', 'आवश्यक प्रकृतिका आपूर्तिकर्ता/निर्माण व्यवसायी/परामर्शदाता/सेवा प्रदायकको मौजुदा सूची तयार/अद्यावधिक गरिएको छ?', 'मौजुदा सूची नराखी/नमिलाई खरिद प्रक्रियालाई कमजोर बनाउने', 'न्यून', 34),
(35, 'PROC-035', 7, 7, 'दर्ता कागजात र वार्षिक अद्यावधिक (Registration & Renewal)', 'नियम १३', 'Registration Certificate, PAN/VAT, Tax Clearance, Business Licence प्रतिलिपि', 'सूचीमा दर्ता गर्दा Registration Certificate, PAN/VAT, Tax Clearance र आवश्यक Business Licence जाँची सूची प्रत्येक आर्थिक वर्ष अद्यावधिक र सार्वजनिक गरिएको छ?', 'नवीकरण/कर चुक्ता नभएका फर्मलाई सूचीमा राखी खरिदमा सहभागी गराउने', 'मध्यम', 35),
(36, 'PROC-036', 7, 7, 'स्वदेशी उत्पादन प्राथमिकता (Domestic Preference)', 'नियम १३', 'स्वदेशी उत्पादन प्राथमिकता प्रमाण, खुला प्रतिस्पर्धा जानकारी', 'सम्भव भएसम्म नेपालमा उत्पादित मालसामानलाई प्राथमिकता दिइएको छ र मौजुदा सूचीमा नभएको बोलपत्रदातालाई खुला प्रतिस्पर्धामा भाग लिनबाट रोकिएको छैन?', 'स्वदेशी उत्पादनको प्राथमिकता नाममात्र राखी विदेशी/निश्चित वस्तुलाई लाभ पुर्याउने', 'न्यून', 36),
(37, 'PROC-037', 8, 8, 'खरिद विधि छनोट (Procurement Method Selection)', 'ऐन दफा ८ / नियम १२', 'विधि छनोट औचित्य टिप्पणी, रकम/प्रकृति विश्लेषण', 'खरिदको प्रकृति र रकमअनुसार उपयुक्त खरिद विधि (अन्तर्राष्ट्रिय/राष्ट्रिय खुला बोलपत्र, सीमित बोलपत्र, दुई चरणको बोलपत्र, सिलबन्दी दरभाउपत्र, सोझै खरिद, उपभोक्ता समिति, अमानत, एकमुष्ट दर, Catalogue Shopping, Limited Tendering, Buy-back; परामर्श सेवामा प्रतिस्पर्धात्मक प्रस्ताव वा सोझै वार्ता) छनोट गरिएको छ?', 'सुविधा/स्वार्थका लागि गलत खरिद विधि छानी प्रतिस्पर्धा सीमित गर्ने', 'अत्यन्त उच्च', 37),
(38, 'PROC-038', 8, 8, 'खुला बोलपत्र प्राथमिकता (Open Competitive Bidding)', 'ऐन दफा ८', 'खुला प्रतिस्पर्धा आह्वान निर्णय, सहभागिता अभिलेख', 'सामान्य अवस्थामा सम्भव भएसम्म खुला बोलपत्र मार्फत खरिद गरी योग्य बोलपत्रदातालाई भेदभावबिना सहभागी हुने अवसर दिइएको छ?', 'औचित्य विना खुला प्रतिस्पर्धा नगर्ने वा योग्य बोलपत्रदातालाई भेदभाव गर्ने', 'उच्च', 38),
(39, 'PROC-039', 8, 8, 'सम्झौता मोडेल र जोखिम छनोट (Contract Model Selection)', 'नियम १४', 'Contract Model छनोट टिप्पणी, PPMO Standard Contract Document, जोखिम/सुपरीवेक्षण तरिका विवरण', 'मालसामान/अन्य सेवाको उपयुक्त सम्झौता, निर्माण कार्यको Contract Model र परामर्श सेवाको सम्झौता छनोट गरी जोखिम कसले वहन गर्ने र Contract Supervision तरिका निर्धारण गरी PPMO को Standard Contract Document प्रयोग गरिएको छ?', 'जोखिम/सुपरीवेक्षण व्यवस्था नखुलाई सम्झौता गरी पछि विवाद र थप लागत सिर्जना गर्ने', 'मध्यम', 39),
(40, 'PROC-040', 9, 9, 'पूर्वयोग्यता आवश्यकता निर्धारण (Prequalification Need)', 'ऐन दफा १२', 'पूर्वयोग्यता आवश्यकता निर्धारण टिप्पणी, कार्य प्रकृति/मूल्य विवरण', 'ठूला/जटिल निर्माण कार्य वा उच्च मूल्यका मालसामान खरिदमा पूर्वयोग्यता आवश्यक छ कि छैन निर्धारण गरिएको छ?', 'पूर्वयोग्यता अनिवार्य नभएकोमा पनि लगाई प्रतिस्पर्धा सीमित गर्ने वा आवश्यक हुँदा नगरी अयोग्य आवेदक भित्र्याउने', 'मध्यम', 40),
(41, 'PROC-041', 9, 9, 'पूर्वयोग्यता प्रस्ताव आह्वान (Prequalification Invitation)', 'ऐन दफा १२', 'पूर्वयोग्यता कागजात, योग्यता निर्धारण आधार, आह्वान सूचना', 'पूर्वयोग्यता कागजात र योग्यता निर्धारणका आधार तयार गरी पूर्वयोग्यताको प्रस्ताव आह्वान गरिएको छ?', 'टेलर-मेड योग्यता राखी सम्भावित प्रतिस्पर्धी बाहिर राख्ने', 'मध्यम', 41),
(42, 'PROC-042', 9, 9, 'पूर्वयोग्यता मूल्याङ्कन र सूची प्रकाशन (Prequalification Evaluation)', 'ऐन दफा १२', 'मूल्याङ्कन प्रतिवेदन, योग्य आवेदकको सूची प्रकाशन प्रमाण', 'प्राप्त प्रस्ताव परीक्षण र तोकिएको आधारमा मूल्याङ्कन गरी योग्य आवेदकको सूची तयार गरी सार्वजनिक गरिएको छ?', 'मूल्याङ्कन नगरी/अधुरो आधारमा मनपरी सूची बनाउने', 'मध्यम', 42),
(43, 'PROC-043', 9, 9, 'अस्वीकृति कारण जानकारी (Reason Disclosure)', 'ऐन दफा १२', 'अस्वीकृत आवेदकलाई कारण सहितको जानकारी पत्र', 'अस्वीकृत आवेदकले कारण मागेमा कारण उपलब्ध गराइएको छ?', 'कारण नदिई वा अस्पष्ट कारण देखाई योग्य आवेदकलाई बाहिर राख्ने', 'न्यून', 43),
(44, 'PROC-044', 10, 10, 'योग्यता मापदण्ड निर्धारण (Qualification Criteria)', 'नियम १५', 'योग्यता मापदण्ड विवरण (Capacity, अनुभव, जनशक्ति, उपकरण, Plant)', 'Technical Capacity, आर्थिक तथा वित्तीय क्षमता, अनुभव, आवश्यक जनशक्ति र उपकरण/Plant, उत्पादन/आपूर्ति क्षमता निर्धारण गरिएको छ?', 'सम्भव नहुने/अत्यधिक कठिन योग्यता राखी सबै प्रतिस्पर्धीलाई अयोग्य बनाउने', 'उच्च', 44),
(45, 'PROC-045', 10, 10, 'Warranty तथा Joint Venture योग्यता (Warranty & JV Criteria)', 'नियम १५', 'Warranty/After-sales/Spare Parts शर्त, JV साझेदार न्यूनतम योग्यता विवरण', 'Warranty/After-sales Service र Spare Parts उपलब्धताको आवश्यकता निर्धारण गरिएको छ र Joint Venture भए साझेदारको न्यूनतम योग्यता निर्धारण गरिएको छ?', 'JV साझेदारको योग्यता कमजोर राखी अनुभव/क्षमता नपुगेको फर्मलाई छनोट गर्ने', 'मध्यम', 45),

(46, 'PROC-046', 10, 10, 'प्रतिस्पर्धा सीमित नगर्ने योग्यता (Non-Restrictive Criteria)', 'नियम १५', 'योग्यता समीक्षा टिप्पणी, भेदभाव नगरिएको विश्लेषण', 'Qualification Criteria ले प्रतिस्पर्धा अनावश्यक रूपमा सीमित नगरेको सुनिश्चित गरिएको छ?', 'निश्चित बोलपत्रदातालाई मात्र पुग्ने योग्यता कायम गरी प्रतिस्पर्धा खण्डित गर्ने', 'उच्च', 46),
(47, 'PROC-047', 11, 11, 'Bid/RFP/RFQ कागजात तयारी (Bidding Document)', 'नियम १६', 'Bid/RFP/RFQ Document, Bidder Instructions, Eligibility/Qualification Criteria', 'Bid/RFP/RFQ Document, Bidder Instructions, Eligibility Criteria र Qualification Criteria तयार गरिएको छ?', 'अपूर्ण कागजातका आधारमा आह्वान गरी विवाद/उजुरीको बाटो खोल्ने', 'मध्यम', 47),
(48, 'PROC-048', 11, 11, 'प्राविधिक सामग्री समावेश (Technical Content)', 'नियम १६', 'Technical Specification, Drawing/Design, BOQ, Delivery/Completion Schedule', 'Technical Specification, Drawing/Design, BOQ र Delivery/Completion Schedule Bid Document मा समावेश गरिएको छ?', 'BOQ/समयतालिका नमिलाई आह्वान गरी पछि म्याद थप/भेरिएसनको बाटो खोल्ने', 'मध्यम', 48),
(49, 'PROC-049', 11, 11, 'जमानत सम्बन्धी व्यवस्था (Security Provisions)', 'नियम १६', 'Bid/Performance/Advance Payment Security व्यवस्था खण्ड', 'Bid Security, Performance Security र Advance Payment Security सम्बन्धी व्यवस्था कागजातमा राखिएको छ?', 'जमानत सम्बन्धी शर्त नराखी सार्वजनिक दायित्व जोखिममा पार्ने', 'उच्च', 49),
(50, 'PROC-050', 11, 11, 'सम्झौता सर्त व्यवस्था (Contract Conditions)', 'नियम १६', 'Contract Conditions, Payment Terms, Warranty/Defect Liability, बीमा, Price Adjustment, Variation, Dispute Resolution व्यवस्था', 'Contract Conditions, Payment Terms, Warranty/Defect Liability, Inspection/Testing, आवश्यक बीमा, Price Adjustment, Variation र Dispute Resolution सम्बन्धी व्यवस्था राखिएको छ?', 'सर्तहरू अपूर्ण राखी पछि मनलाग्दी भुक्तानी/भेरिएसनको बाटो बनाउने', 'उच्च', 50),
(51, 'PROC-051', 11, 11, 'थप व्यवस्थाहरू (Additional Clauses)', 'ऐन दफा ४ / नियम १६', 'Site Visit/Pre-bid, Evaluation Method, Domestic Preference, Review/Complaint Mechanism खण्ड', 'Site Visit, Pre-bid Meeting, Price Structure, Currency, Evaluation Method, Domestic Preference, Package/Group, Alternative Proposal, Bid Validity, Conflict of Interest, Fraud/Corruption तथा Review/Complaint Mechanism सम्बन्धी व्यवस्था समावेश गरिएको छ?', 'उजुरी/पुनरावलोकन व्यवस्था नराखी बोलपत्रदाताको अधिकार खोस्ने', 'मध्यम', 51),
(52, 'PROC-052', 11, 11, 'मालसामानको Technical Specification (Goods Specification)', 'नियम ४२–४५', 'भौतिक/रासायनिक विशेषता, Performance Requirement, Spare Parts, Testing Method विवरण', 'मालसामानको Technical Specification मा भौतिक/रासायनिक विशेषता, Performance Requirement, Configuration, Spare Parts, Catalogue/Sample, Quality Guarantee, Warranty/Maintenance, Environmental Requirement र Testing Method उल्लेख गरिएको छ?', 'परीक्षण विधि/गुणस्तर सर्त नखुलाई गुणस्तर विवाद सिर्जना गर्ने', 'मध्यम', 52),
(53, 'PROC-053', 11, 11, 'निर्माण कार्यको Technical Specification (Works Specification)', 'नियम ४२–४५', 'Scope of Work, Site Condition, Design, BOQ, Completion/Performance Test, As-built Drawing विवरण', 'निर्माण कार्यको Technical Specification मा Scope of Work, Site Condition, Design, BOQ, Environmental Requirement, Equipment/Parts, Quality Requirement, Inspection & Testing, Completion Test, As-built Drawing, Operation Manual, Performance Test र समयतालिका उल्लेख गरिएको छ?', 'गुणस्तर/परीक्षण शर्त खुलाउन छुटाई न्यून गुणस्तरको काम स्वीकार्ने बाटो बनाउने', 'उच्च', 53),
(54, 'PROC-054', 11, 11, 'कागजात स्वीकृति (Document Approval)', 'नियम १८', 'स्वीकृति टिप्पणी, अधिकार प्राप्त अधिकारीको निर्णय', 'तयार गरिएको Bid/RFP/EOI कागजात जाँची अधिकार प्राप्त अधिकारीबाट स्वीकृत गराई स्वीकृति भएपछि मात्र आह्वान गरिएको छ?', 'स्वीकृति विना आह्वान गरी प्रक्रिया नै अनियमित बनाउने', 'उच्च', 54),
(55, 'PROC-055', 12, 12, 'आह्वान सूचना तयारी (Invitation Notice)', 'नियम १९', 'बोलपत्र/पूर्वयोग्यता आह्वान सूचना, National/International निर्णय टिप्पणी', 'बोलपत्र/पूर्वयोग्यता आह्वानको सूचना तयार गरी National/International Bid को निर्णय गरिएको छ?', 'अन्तर्राष्ट्रिय प्रतिस्पर्धा गर्नुपर्नेमा राष्ट्रिय मात्र गरी प्रतिस्पर्धा सीमित गर्ने', 'मध्यम', 55),
(56, 'PROC-056', 12, 12, 'सूचना प्रकाशन (Publication of Notice)', 'ऐन दफा १४ / नियम १९', 'राष्ट्रिय दैनिक पत्रिकाको कटिङ, वेबसाइट/e-GP प्रकाशन प्रमाण', 'राष्ट्रिय दैनिकमा सूचना प्रकाशित गरिएको छ र आवश्यक भए वेबसाइट तथा अन्तर्राष्ट्रिय खरिदमा अन्तर्राष्ट्रिय सञ्चार माध्यम/अंग्रेजी भाषामा प्रकाशित गरिएको छ?', 'न्यून प्रचलनको माध्यमबाट सूचना निकाली प्रतिस्पर्धा सीमित पार्ने', 'उच्च', 56),
(57, 'PROC-057', 12, 12, 'कागजात उपलब्धता र e-GP (Document Availability)', 'नियम १९', 'Bid Document वितरण/Access अभिलेख, दस्तुर रसिद, e-GP प्रवाह', 'Bid Document उपलब्ध गराई तोकिएको दस्तुर लिइएको छ र Electronic Bid भए e-GP मार्फत व्यवस्था गरिएको छ?', 'दस्तुर नलिई/छुट दिई निश्चित बोलपत्रदातालाई मात्र सहजता दिने', 'मध्यम', 57),
(58, 'PROC-058', 12, 12, 'म्याद निर्धारण (Submission Deadline)', 'ऐन दफा १४ / नियम १९', 'तय भएको Bid Submission Deadline र Bid Opening मिति/समय/स्थान अभिलेख', 'Bid Submission Deadline र Bid Opening Date/Time/Place तोकिएको छ (राष्ट्रिय बोलपत्रमा कम्तीमा ३० दिन, अन्तर्राष्ट्रियमा कम्तीमा ४५ दिन)?', 'कानूनी न्यूनतम म्याद घटाई प्रतिस्पर्धा सीमित गर्ने', 'उच्च', 58),
(59, 'PROC-059', 12, 12, 'Pre-bid Meeting (Pre-bid Meeting)', 'नियम १९', 'Pre-bid बैठक माइन्युट, प्रश्नोत्तर सबैलाई समान उपलब्ध गराइएको प्रमाण', 'आवश्यक भए Pre-bid Meeting आयोजना गरी Bidder का प्रश्नको जवाफ सबैलाई समान रूपमा उपलब्ध गराइएको छ?', 'निश्चित प्रतिस्पर्धीलाई मात्र भित्री जानकारी दिने', 'मध्यम', 59),
(60, 'PROC-060', 12, 12, 'संशोधन/Clarification (Amendment)', 'नियम १९', 'संशोधन सूचना, म्याद थप निर्णय, सबै सहभागीलाई जानकारी प्रमाण', 'आवश्यक संशोधन/Clarification जारी गर्दा सबै सहभागीलाई जानकारी दिई आवश्यक भए Bid Submission Deadline बढाइएको छ?', 'संशोधन गरी म्याद नथपी निश्चित पक्षलाई मात्र सूचित गर्ने', 'मध्यम', 60),
(61, 'PROC-061', 12, 12, 'Bid Security शर्त (Bid Security Terms)', 'नियम २०', 'Bid Security रकम/माध्यम/Validity उल्लेख, सबैलाई समान लागू भएको प्रमाण', 'Bid Security रकम, स्वीकार्य माध्यम (Cash/Bank Guarantee) र Validity सम्बन्धी शर्त स्पष्ट गरी सबै बोलपत्रदातालाई समान रूपमा लागू हुने व्यवस्था गरिएको छ?', 'कम जमानत/छुट्टै मापदण्ड लगाई विशेष बोलपत्रदातालाई सहज बनाउने', 'मध्यम', 61),
(62, 'PROC-062', 13, 13, 'Bid दर्ता (Bid Registration)', 'नियम २१', 'बोलपत्र दर्ता किताब/लग, e-GP सबमिसन अभिलेख', 'निर्धारित समयभित्र प्राप्त Bid दर्ता गरिएको छ र Deadline पछि प्राप्त बोलपत्र स्वीकार गरिएको छैन?', 'म्याद नाघेपछि आएको बोलपत्र स्वीकार गर्ने', 'अत्यन्त उच्च', 62),
