(74, 'PROC-074', 15, 15, 'Substantially Responsive निर्धारण (Substantial Responsiveness)', 'ऐन दफा २५ / नियम २४', 'Substantial Responsiveness निर्धारण निर्णय', 'Substantially Responsive Bid निर्धारण गरिएको छ?', 'आधार नखुलाई सुविधानुसार प्रभावग्राही/गैर-प्रभावग्राही ठहर गर्ने', 'उच्च', 74),
(75, 'PROC-075', 16, 16, 'आर्थिक मूल्याङ्कन (Financial Evaluation)', 'ऐन दफा २५ / नियम २५', 'आर्थिक मूल्याङ्कन तालिका, Transportation/Technical मूल्य प्रभाव गणना', 'Responsive Bid हरूको आर्थिक मूल्याङ्कन गरी आवश्यक भए Internal Transportation Cost र Technical Features को मूल्य प्रभाव समावेश गरिएको छ?', 'मूल्य प्रभाव नगणना गरी सुविधानुसार न्यूनतम छनोट गर्ने', 'उच्च', 75),
(76, 'PROC-076', 16, 16, 'Currency/Discount समायोजन (Currency & Discount)', 'नियम २५', 'Currency Conversion गणना, Discount समायोजन अभिलेख', 'Currency Conversion र Discount समायोजन गरी Evaluated Bid Price निकालिएको छ?', 'विनिमय दर मनपरी लिई निश्चित बोलपत्रदातालाई लाभ पुर्याउने', 'मध्यम', 76),
(77, 'PROC-077', 16, 16, 'Lowest Evaluated छनोट र पुनःजाँच (Lowest Evaluated Selection)', 'ऐन दफा २५ / नियम २५', 'Evaluated Price तुलना तालिका, Qualification पुनःजाँच अभिलेख', 'न्यूनतम मूल्याङ्कित सारभूतरूपमा प्रभावग्राही (Lowest Evaluated Substantially Responsive) बोलपत्र पहिचान गरी सोको Qualification पुनः जाँच गरिएको छ र आवश्यक भए अर्को न्यूनतम बोलपत्रतर्फ गइएको छ?', 'सबैभन्दा कम मूल्य नहुने बोलपत्रलाई कृत्रिम आधारमा छनोट गर्ने', 'अत्यन्त उच्च', 77),
(78, 'PROC-078', 17, 17, 'विस्तृत Evaluation Report (Evaluation Report)', 'नियम २६', 'नाम/ठेगाना, Bid Amount, Corrected Amount, Evaluated Price सहितको मूल्याङ्कन प्रतिवेदन', 'Bidder को नाम/ठेगाना, Bid Amount, Corrected Amount, Discount, Currency Conversion, Evaluation Basis, Evaluated Price र सफल/असफल Bidder को विवरण खुलाई विस्तृत Evaluation Report तयार गरिएको छ?', 'अपूर्ण प्रतिवेदन बनाई मूल्याङ्कन पारदर्शी नबनाउने', 'उच्च', 78),
(79, 'PROC-079', 17, 17, 'प्रतिवेदन पेश (Report Submission)', 'ऐन दफा २५ / नियम २६', 'मूल्याङ्कन समितिको प्रतिवेदन पेश अभिलेख, स्वीकृति टिप्पणी', 'मूल्याङ्कन समितिबाट अधिकार प्राप्त अधिकारीसमक्ष प्रतिवेदन पेश गरिएको छ?', 'समितिको सिफारिस बेवास्ता गरी फरक निर्णय गर्ने', 'उच्च', 79),
(80, 'PROC-080', 17, 17, 'रद्द/अस्वीकार अवस्था जाँच (Cancellation Check)', 'ऐन दफा २६', 'रद्द निर्णय, कारण सहितको सूचना सबै बोलपत्रदातालाई', 'कुनै बोलपत्र सारभूत रूपमा प्रभावग्राही नभएमा, सम्झौता हुन नसक्ने अवस्था भएमा, न्यूनतम प्रभावग्राही बोलपत्र लागत अनुमानभन्दा सारभूत रूपमा बढी भएमा वा खरिद आवश्यक नै नरहेमा कारणसहितको सूचना सबैलाई दिई रद्द/बोलपत्र अस्वीकार निर्णय गरिएको छ?', 'कारण नखुलाई मनपरी रद्द गर्ने वा रद्द गर्नुपर्ने अवस्थामा पनि स्वीकार गर्ने', 'मध्यम', 80),
(81, 'PROC-081', 18, 18, 'बोलपत्र/प्रस्ताव स्वीकृति (Award Approval)', 'ऐन दफा २७ / नियम २७', 'Evaluation Recommendation, स्वीकृति निर्णय/टिप्पणी', 'Evaluation Recommendation प्राप्त गरी अधिकार प्राप्त अधिकारीबाट बोलपत्र/प्रस्ताव स्वीकृत गराइएको छ?', 'सिफारिस विपरित वा आधार विना स्वीकृति दिने', 'अत्यन्त उच्च', 81),
(82, 'PROC-082', 18, 18, 'Letter of Intent जारी (Letter of Intent)', 'ऐन दफा २७', 'LOI पत्र, सूचना प्रकाशन प्रमाण, अन्य बोलपत्रदातालाई जानकारी', 'सफल बोलपत्रदातालाई ७ दिनभित्र Letter of Intent/स्वीकृतिको आशयको सूचना दिइएको छ र छनोट भएको नाम, ठेगाना र रकम अन्य बोलपत्रदातालाई जानकारी दिइएको छ?', 'LOI नदिई वा ढिलो गरी सिधै सम्झौता गर्ने', 'उच्च', 82),
(83, 'PROC-083', 18, 18, 'पुनरावलोकन/उजुरी अवसर (Review Opportunity)', 'ऐन दफा २७, ४७–५०', 'उजुरी व्यवस्थापन अभिलेख, अवधि पूरा भएको प्रमाण', 'सम्बन्धित पक्षलाई पुनरावलोकन/उजुरीको अवसर दिई आवश्यक अवधि पूरा भएपछि बोलपत्र स्वीकृत गरिएको छ?', 'उजुरी अवधि नपर्खी स्वीकृति/सम्झौता गर्ने', 'उच्च', 83),
(84, 'PROC-084', 18, 18, 'Performance Security/कागजात माग (Security Demand)', 'ऐन दफा २७ / नियम २७', 'Performance Security दाखिला कागजात, अन्य Security/कागजात, अर्को बोलपत्रदातातर्फ जाने निर्णय (भए)', 'Performance Security र आवश्यक अन्य Security/कागजात माग गरिएको छ र तोकिएको अवधिमा दाखिला नगरी सम्झौता गर्न नआएमा अर्को योग्य बोलपत्रदातातर्फ जान सकिने व्यवस्था गरिएको छ?', 'जमानत विना/अपुग जमानतमा सम्झौता गर्ने', 'उच्च', 84),
(85, 'PROC-085', 19, 19, 'सम्झौता अन्तिम कागजात (Final Contract Documents)', 'नियम २७', 'अन्तिम सम्झौता कागजात, अधिकार प्राप्त अधिकारीको स्वीकृति', 'सम्झौताको अन्तिम कागजात तयार गरी अधिकार प्राप्त अधिकारीबाट स्वीकृति लिइएको छ?', 'स्वीकृति विना सम्झौता मस्यौदा प्रयोग गर्ने', 'मध्यम', 85),
(86, 'PROC-086', 19, 19, 'सम्झौता सर्त समावेश (Contract Clauses)', 'ऐन दफा ५२', 'पूर्ण सम्झौता पत्र (सबै अनिवार्य खण्ड सहित)', 'सम्झौतामा पक्षहरूको विवरण, Contract Scope/Documents, Work Schedule, Contract Price, Payment Terms, Acceptance Conditions, Force Majeure, Price Adjustment, Contract Amendment, Variation, बीमा, Securities, Liquidated Damages, Bonus, Termination, Sub-contracting, Dispute Resolution र Applicable Law समावेश गरिएको छ?', 'बोलपत्रका सर्तभन्दा फरक/अपूर्ण सम्झौता गरी सार्वजनिक दायित्व सिर्जना गर्ने', 'उच्च', 86),
(87, 'PROC-087', 19, 19, 'सम्झौता हस्ताक्षर (Contract Signing)', 'नियम २७', 'हस्ताक्षरित सम्झौता, सम्बन्धित पक्षलाई प्रति उपलब्ध गराइएको प्रमाण', 'अधिकार प्राप्त व्यक्तिबाट Contract Sign गरी सम्बन्धित पक्षलाई सम्झौताको प्रति उपलब्ध गराइएको छ?', 'अनधिकार व्यक्तिबाट हस्ताक्षर गराउने वा प्रति उपलब्ध नगर्ने', 'मध्यम', 87),
(88, 'PROC-088', 20, 20, 'Security र बीमा प्राप्ति (Security & Insurance Receipt)', 'नियम २८', 'Performance Security, Advance Payment Security, Insurance Policy', 'Performance Security प्राप्त गरिएको छ र आवश्यक भए Advance Payment Security र Insurance Policy लिइएको छ?', 'काम सुरु गराउनुअघि जमानत/बीमा नलिने वा म्याद नबढाउने', 'उच्च', 88),
(89, 'PROC-089', 20, 20, 'कार्यान्वयन टोली र योजना (Implementation Setup)', 'नियम २८', 'Work Programme/Mobilization Plan, Contract Implementation Team गठन, Contract Administration Plan', 'Work Programme/Mobilization Plan जाँची Contract Implementation Team गठन गरी Contract Administration Plan तयार गरिएको छ?', 'सुपरीवेक्षण संरचना विना ठेकेदारलाई छाडा छोड्ने', 'मध्यम', 89),
(90, 'PROC-090', 20, 20, 'Site Handover र कार्यादेश (Site Handover & Work Order)', 'नियम २८', 'Site Handover मुचुल्का, Site Access सुनिश्चितता, कार्य प्रारम्भ आदेश', 'Site Handover गरी Site Access सुनिश्चित गराई कार्य प्रारम्भ आदेश दिइएको छ?', 'साइट हस्तान्तरण मिति नराखी दायित्व अस्पष्ट पार्ने', 'मध्यम', 90),
(91, 'PROC-091', 21, 21, 'प्रगति अनुगमन र Quality Test (Progress & Quality)', 'नियम २९', 'अनुगमन प्रतिवेदन, Quality Inspection अभिलेख, Laboratory/Quality Test Report', 'कार्य प्रगति नियमित अनुगमन गरी Quality Inspection र Laboratory/Quality Test गराइएको छ?', 'अनुगमन/परीक्षण नगराई न्यून गुणस्तरको काम स्वीकार्ने', 'अत्यन्त उच्च', 91),
(92, 'PROC-092', 21, 21, 'स्थलगत निरीक्षण र Progress Report (Site Inspection)', 'नियम २९', 'स्थलगत निरीक्षण अभिलेख, Work Programme तुलना, Progress Report', 'निर्माणस्थल निरीक्षण गरी Work Programme अनुसार प्रगति तुलना गरिएको छ र Contractor/Supplier/Consultant बाट Progress Report लिइएको छ?', 'कागजी प्रगति देखाई वास्तविक काम नभएको अवस्था लुकाउने', 'उच्च', 92),
(93, 'PROC-093', 21, 21, 'नापी किताब (Measurement Book)', 'नियम २९', 'Measurement Book (MB), स्थलगत नापजाँच अभिलेख, निर्देशन अभिलेख, Defect Correction अभिलेख', 'Site Measurement गरी Measurement Book/सम्बन्धित अभिलेख राखिएको छ, आवश्यक निर्देशन दिइएको छ र Defect देखिए Correction गराइएको छ?', 'काम नगरिएको वा वास्तविक भन्दा बढी परिमाण नापी किताबमा चढाउने', 'अत्यन्त उच्च', 93),
(94, 'PROC-094', 21, 21, 'Safety र Environmental जाँच (Safety & Environment)', 'नियम २९', 'Safety/Environmental अनुगमन अभिलेख, OHS प्रतिवेदन', 'Safety/Environmental Requirement र Contract Documents अनुसार काम भए/नभएको जाँच गरिएको छ?', 'सुरक्षा/वातावरणीय सर्त पालना नगराई जोखिममा काम गराउने', 'मध्यम', 94),
(95, 'PROC-095', 21, 21, 'निकाय प्रमुखको सुपरीवेक्षण (Head of Entity Supervision)', 'ऐन दफा ७(६)', 'सुपरीवेक्षण/अनुगमन अभिलेख, समीक्षा बैठक माइन्युट', 'सम्बन्धित सार्वजनिक निकायको प्रमुखले नियमित सुपरीवेक्षण, अनुगमन र गुणस्तर नियन्त्रण गरी वा गराई निर्धारित समयमा कार्य सम्पन्न हुने सुनिश्चितता गरेको छ?', 'निकाय प्रमुखको संलग्नता विना आयोजना अलपत्र पर्ने', 'मध्यम', 95),
(96, 'PROC-096', 22, 22, 'पेश्की र Advance Guarantee (Advance Payment)', 'ऐन दफा ५२क', 'Advance Bank Guarantee, पेश्की भुक्तानी निर्णय', 'पेश्की दिइने भए Advance Bank Guarantee लिई सम्झौता रकमको तोकिएको सीमा (बढीमा २० प्रतिशत) भित्र मात्र पेश्की दिइएको छ?', 'जमानत विना/सीमा नाघेर पेश्की दिने', 'अत्यन्त उच्च', 96),
(97, 'PROC-097', 22, 22, 'पेश्की प्रयोग अनुगमन र कट्टा (Advance Recovery)', 'ऐन दफा ५२क / नियम ३०', 'पेश्की प्रयोग विवरण, Running Bill बाट कट्टा अभिलेख', 'पेश्कीको प्रयोग अनुगमन गरी विवरण अद्यावधिक राखिएको छ र Advance लाई Running Bill बाट कट्टा गरिएको छ?', 'पेश्की कट्टा नगरी पूरै भुक्तानी गर्ने', 'उच्च', 97),
(98, 'PROC-098', 22, 22, 'Running Bill जाँच (Running Bill Verification)', 'नियम ३०', 'Running Bill/Invoice, Measurement Verification, Work Progress Verification, Quality Test Report', 'Running Bill/Invoice प्राप्त गरी Measurement र Work Progress Verification गराई Quality Test Report जाँच गरिएको छ?', 'नापजाँच/प्रगति प्रमाणन विना रनिङ बिल भुक्तानी गर्ने', 'अत्यन्त उच्च', 98),
(99, 'PROC-099', 22, 22, 'भुक्तानी र कट्टी (Payment & Deductions)', 'ऐन दफा ५७ / नियम ३०', 'बिल/विजक परीक्षण, Tax/VAT कट्टी अभिलेख, Payment Record', 'Tax/VAT लगायत आवश्यक कट्टी गरी सम्झौताअनुसार बिल/विजक परीक्षण गरी भुक्तानी गरिएको छ र Payment Record राखिएको छ?', 'कट्टी नगरी/गलत कट्टी गरी भुक्तानी गर्ने', 'उच्च', 99),
(100, 'PROC-100', 23, 23, 'Variation औचित्य र Justification (Variation Justification)', 'ऐन दफा ५४ / नियम ३१', 'Variation औचित्य अभिलेख, Technical Justification, Revised Cost', 'अप्रत्याशित परिस्थिति भए Variation आवश्यक छ कि छैन जाँची कारण अभिलेख गरिएको छ र Technical Justification र Revised Cost तयार गरिएको छ?', 'औचित्य विना Variation गरी रकम बढाउने', 'अत्यन्त उच्च', 100);
INSERT INTO checklist_items (id, checklist_code, stage_id, stage_number, inspection_area, legal_reference, required_documents, inspection_question, possible_irregularity, default_risk_level, sort_order) VALUES
(101, 'PROC-101', 23, 23, 'Variation Order स्वीकृति (Variation Approval)', 'ऐन दफा ५४ / नियम ३१', 'Variation Order, Written Order, Cumulative Amount अभिलेख', 'अधिकार प्राप्त अधिकारीबाट Variation Order स्वीकृत गराई Contract को मूल प्रकृति नबिग्रने सुनिश्चित गरी Written Order जारी गरिएको छ र Cumulative Amount को अभिलेख राखिएको छ?', 'काम गराइसकेपछि पछाडि फर्केर मनलाग्दी Variation स्वीकृत गर्ने', 'अत्यन्त उच्च', 101),
(102, 'PROC-102', 23, 23, 'Contract Amendment (Contract Amendment)', 'ऐन दफा ५३', 'लिखित सहमति/संशोधन कागजात, स्वीकृति निर्णय', 'Contract Amendment आवश्यक भए लिखित सहमति गरिएको छ?', 'मौखिक/अनौपचारिक संशोधन गरी पछि विवाद सिर्जना गर्ने', 'मध्यम', 102),
(103, 'PROC-103', 23, 23, 'मूल्य समायोजन (Price Adjustment)', 'ऐन दफा ५५ / नियम ३२', 'मूल्य समायोजन गणना, Contract Formula, Eligibility Period जाँच अभिलेख', 'Price Adjustment लागू हुने/नहुने र Eligibility Period जाँची Contract मा भएको Formula अनुसार गणना गरिएको छ र Contractor को ढिलाइका कारण Adjustment दिनुपर्ने/नपर्ने जाँच गरिएको छ?', 'सर्त नभएको अवस्थामा वा ढिलाइको अवधिभर पनि मनलाग्दी मूल्य समायोजन दिने', 'उच्च', 103),
(104, 'PROC-104', 23, 23, 'म्याद थप (Extension of Time)', 'ऐन दफा ५६ / नियम ३३', 'म्याद थप आवेदन, औचित्य जाँच, Extension Recommendation, Revised Completion Date अभिलेख', 'म्याद थपको आवेदन प्राप्त गरी कारण, Force Majeure/Public Body को कारणले ढिलाइ भए/नभएको र वास्तविक प्रगति जाँची Extension Recommendation तयार गराई अधिकार प्राप्त अधिकारीबाट स्वीकृत गराई Revised Completion Date अभिलेख गरिएको छ?', 'औचित्य जाँच नगरी/हर्जना नलगाई पटक-पटक म्याद थप्ने', 'उच्च', 104),
(105, 'PROC-105', 24, 24, 'Completion Test/Technical Inspection (Completion Test)', 'नियम ३४', 'Completion Request, Technical Inspection Report, Completion Test Report, Defect सुधार अभिलेख', 'Completion Request लिई Technical Inspection र Completion Test गरी Specification अनुसार काम भए/नभएको जाँच गरी Defect सुधार गराइएको छ?', 'परीक्षण विना अपुरो/न्यून गुणस्तरको कामलाई सम्पन्न भनी स्वीकार्ने', 'अत्यन्त उच्च', 105),
(106, 'PROC-106', 24, 24, 'Completion Report र प्रमाणपत्र (Completion Certificate)', 'नियम ३४', 'As-built Drawing, Operating/Maintenance Manual, Completion Report, Completion Certificate, Final Measurement', 'As-built Drawing र Operating/Maintenance Manual लिई Completion Report तयार गरी कार्य स्वीकार/Completion Certificate जारी गरी Final Measurement गरिएको छ?', 'As-built Drawing/म्यानुअल विना सम्पन्न प्रमाणपत्र जारी गर्ने', 'उच्च', 106),
(107, 'PROC-107', 24, 24, 'Final Bill जाँच (Final Bill Verification)', 'नियम ३५', 'Final Bill, Final Measurement Verification, Variation/Price Adjustment समायोजन, Advance Recovery अभिलेख', 'Final Bill प्राप्त गरी Final Measurement Verify गरिएको छ र सबै Variation र Price Adjustment समायोजन गरी Advance Recovery पूरा भएको जाँच गरिएको छ?', 'Final Measurement नगरी/समायोजन नगरी अन्तिम बिल भुक्तानी गर्ने', 'उच्च', 107),
(108, 'PROC-108', 24, 24, 'Final Payment र Close-out (Final Payment & Close-out)', 'नियम ३५', 'LD गणना, Tax/Retention/कट्टी अभिलेख, Final Payment भौचर, Contract Close-out Report', 'Liquidated Damages भए गणना गरी Tax/Retention/अन्य कट्टी जाँची Final Payment गरिएको छ र Performance Security/Retention व्यवस्था सम्झौताअनुसार पूरा गरी Contract Close-out Report तयार गरिएको छ?', 'कट्टी नगरी पूरै भुक्तानी गरी अपूर्ण फरफारक गर्ने', 'अत्यन्त उच्च', 108),
(109, 'PROC-109', 25, 25, 'Default अभिलेख र Notice (Notice to Correct)', 'ऐन दफा ५९ / नियम ३६', 'Default अभिलेख, Notice पत्र, सुधारका लागि दिइएको समय अभिलेख', 'Contractor/Supplier/Consultant को Default अभिलेख गरी Notice जारी गराइएको छ र सुधारका लागि आवश्यक समय दिइएको छ?', 'Default अभिलेख नराखी/सूचना नदिई सिधै कारबाही गर्ने वा ढिलो गर्ने', 'मध्यम', 109),
(110, 'PROC-110', 25, 25, 'Remedies र जमानत जफत (Remedies & Forfeiture)', 'ऐन दफा ५९ / नियम ३६', 'Remedies प्रयोग अभिलेख, Performance Security जफत पत्र, Advance दुरुपयोग कारबाही अभिलेख', 'आवश्यक भए Contract का remedies प्रयोग गरिएको छ, Performance Security जफत गरिएको छ र Advance दुरुपयोग भएमा Security सम्बन्धी कारबाही गरिएको छ?', 'जफत गर्नुपर्ने जमानत नजफत गरी छुट दिने', 'उच्च', 110),
(111, 'PROC-111', 25, 25, 'सम्झौता अन्त्य र बाँकी काम (Termination & Re-procurement)', 'ऐन दफा ५९ / नियम ३६', 'Contract Termination निर्णय, बाँकी कार्य लागत निर्धारण, नयाँ खरिद प्रक्रिया कागजात', 'आवश्यक भए Contract Terminate गरी बाँकी कार्यको लागत निर्धारण गरिएको छ र बाँकी काम पूरा गर्न आवश्यक भए नयाँ खरिद प्रक्रिया सुरु गरिएको छ?', 'अलपत्र सम्झौता अन्त्य नगरी बाँकी काम अनिश्चितकाल राख्ने', 'उच्च', 111),
