(114, 'PROC-114', 25, 25, 'विवाद समाधान (Dispute Resolution)', 'ऐन दफा ५८', 'विवाद समाधान अभिलेख, सलाहकार/मध्यस्थता कारबाही कागजात', 'सम्झौतासँग सम्बन्धित विवाद उत्पन्न भएमा तोकिएको विवाद समाधान संयन्त्र (Dispute Resolution) प्रयोग गरिएको छ?', 'तोकिएको प्रक्रिया नअपनाई विवाद लम्ब्याउने वा सिधै अदालत जाने', 'न्यून', 114),
(115, 'PROC-115', 26, 26, 'विशेष विधि अपनाउने (Special Methods Application)', 'नियम ३७', 'विशेष विधि औचित्य टिप्पणी, सम्बन्धित नियम पालना प्रमाण', 'सिलबन्दी दरभाउपत्र, सोझै खरिद, सीमित बोलपत्र, दुई चरणको बोलपत्र, विशेष परिस्थितिको खरिद, उपभोक्ता समिति, लाभग्राही समुदाय र अमानत विधि आवश्यकता अनुसार अपनाइएको छ?', 'सामान्य खरिदलाई विशेष विधिमा पारी प्रतिस्पर्धा छल्ने', 'अत्यन्त उच्च', 115),
