(133, 'PROC-133', 32, 32, 'विशेष परिस्थितिको खरिद (Emergency Procurement)', 'ऐन दफा ६६', 'विपद्/आकस्मिकता प्रमाण, तत्काल खरिद औचित्य/स्वीकृति अभिलेख', 'भूकम्प, बाढी, पहिरो, आगलागी, महामारी वा अन्य आकस्मिक विशेष परिस्थितिमा तत्काल खरिद नगर्दा थप हानि हुने अवस्था भए विशेष प्रक्रियाबाट खरिद गरिएको छ?', 'विशेष परिस्थितिको दुरुपयोग गरी मनलाग्दी खरिद गर्ने', 'अत्यन्त उच्च', 133),
(134, 'PROC-134', 32, 32, 'माथिल्लो तहलाई जानकारी (Reporting to Higher Authority)', 'ऐन दफा ६६', 'परिस्थिति र खरिदको विस्तृत विवरण सहितको जानकारी पत्र', 'सार्वजनिक निकायका प्रमुखले परिस्थिति र तत्काल गरिएको खरिदको विस्तृत विवरण एक तह माथिको अधिकारीलाई जानकारी दिएको छ?', 'जानकारी नदिई/ढिलो गरी विशेष खरिद लुकाउने', 'उच्च', 134),
(135, 'PROC-135', 33, 33, 'Procurement File आधारभूत कागजात (Core File)', 'ऐन दफा ७२ / नियम ३९', 'खरिद माग, बजेट प्रमाण, Specification, Design/Drawing, Cost Estimate र स्वीकृति कागजात', 'प्रत्येक खरिदको Procurement File मा खरिद माग, बजेट प्रमाण, Specification, Design/Drawing, Cost Estimate र सोको स्वीकृति व्यवस्थित राखिएको छ?', 'आधारभूत कागजात मिसिलमा नराखी पछि प्रमाण अभाव सिर्जना गर्ने', 'मध्यम', 135),
(136, 'PROC-136', 33, 33, 'योजना/आह्वान कागजात अभिलेख (Plan & Invitation Records)', 'नियम ३९', 'Procurement Plan, Bid/RFP/EOI Document, Bid Notice, Distribution/Access Record, Pre-bid Minutes, Clarification/Amendment', 'Procurement Plan, Bid/RFP/EOI Document, Bid Notice, Bid Distribution/Access Record, Pre-bid Meeting Minutes र Clarification/Amendment व्यवस्थित राखिएको छ?', 'कागजात अभाव बनाई जाँच/अनुगमनमा असहयोग गर्ने', 'मध्यम', 136),
(137, 'PROC-137', 33, 33, 'मूल्याङ्कन/सम्झौता अभिलेख (Evaluation & Contract Records)', 'नियम ३९', 'Bid/Proposal, Opening Minutes, Evaluation Report, Approval Decision, LOI, Performance Security, Contract, Insurance, Advance Security', 'प्राप्त Bid/Proposal, Bid Opening Minutes, Evaluation Documents/Report, Approval Decision, Letter of Intent, Performance Security, Contract, Insurance र Advance Security व्यवस्थित राखिएको छ?', 'मूल्याङ्कन/सम्झौता कागजात हराउने वा मिलान नहुने कागजात राख्ने', 'उच्च', 137),
(138, 'PROC-138', 33, 33, 'कार्यान्वयन अभिलेख (Implementation Records)', 'नियम ३९', 'Work Programme, Progress Reports, Inspection/Test Reports, Measurement Records, Running Bills, Payment Records', 'Work Programme, Progress Reports, Inspection/Test Reports, Measurement Records, Running Bills र Payment Records व्यवस्थित राखिएको छ?', 'नापजाँच/परीक्षण अभिलेख नराखी भुक्तानी प्रमाणित गर्ने', 'उच्च', 138),
(139, 'PROC-139', 33, 33, 'परिवर्तन/समापन अभिलेख (Variation & Close-out Records)', 'नियम ३९', 'Variation/Extension Orders, Price Adjustment, Correspondence, Completion Certificate, Final Bill, Close-out Documents', 'Variation Orders, Extension Orders, Price Adjustment, Correspondence, Completion Certificate, Final Bill र Contract Close-out Documents व्यवस्थित राखिएको छ?', 'परिवर्तन/समापन कागजात अभाव बनाई जवाफदेहिता छल्ने', 'मध्यम', 139),
(140, 'PROC-140', 33, 33, 'अभिलेख संरक्षण अवधि (Retention Period)', 'ऐन दफा ७२', 'अभिलेख संरक्षण अभिलेख, मिसिल हस्तान्तरण लग', 'सम्पूर्ण खरिद कारबाहीसम्बन्धी कागजातको अभिलेख तोकिएको अवधिसम्म सुरक्षित राखिएको छ?', 'तोकिएको अवधि नपुग्दै कागजात नष्ट गर्ने/हराउने', 'मध्यम', 140),
(141, 'PROC-141', 34, 34, 'खरिद अधिकारीको निरन्तर जिम्मेवारी (Continuous Responsibility)', 'नियम ११, ४३', 'अद्यावधिक खरिद योजना, खरिद माग संकलन अभिलेख, समन्वय अभिलेख, Procurement Progress Track', 'खरिद अधिकारीले खरिद योजना अद्यावधिक गर्ने, खरिद माग संकलन गर्ने, खरिद प्रक्रियाको समन्वय गर्ने, Bid/Proposal Opening व्यवस्थापन गर्ने र Procurement/Security/Extension Records राखी Procurement Progress Track गरेको छ?', 'खरिद अधिकारीले योजना/अभिलेख अद्यावधिक नगरी प्रक्रिया थन्क्याउने', 'मध्यम', 141),
(142, 'PROC-142', 34, 34, 'अन्तिम आन्तरिक Procurement Audit/Review (Final Internal Audit)', 'नियम ४४', 'Planning देखि Disclosure सम्मको सम्पूर्ण cycle प्रमाणित गर्ने कागजात सहितको आन्तरिक जाँच प्रतिवेदन', 'हरेक खरिद सम्पन्न भएपछि Planning → Budget → Specification → Cost Estimate → Method → Bid Document → Notice → Bid Receipt → Opening → Evaluation → Approval → Contract → Security → Implementation → Inspection → Measurement → Payment → Variation → Extension → Completion → Final Payment → Record → Disclosure सम्मको सम्पूर्ण procurement cycle प्रमाणित हुने कागजातसहित आन्तरिक रूपमा जाँच गरिएको छ?', 'आन्तरिक जाँच नगरी त्रुटि/अनियमितता लुकाउने', 'उच्च', 142);

-- 6) पुराना inspection results, findings र evidence links पुनःस्थापना
INSERT INTO inspection_checklist_results (
    inspection_id, checklist_item_id, compliance_status, risk_level, evidence_reference,
    observation, financial_impact, inspector_comment, completed_by, completed_at, created_at, updated_at
)
SELECT s.inspection_id, ci.id, s.compliance_status, s.risk_level, s.evidence_reference,
       s.observation, s.financial_impact, s.inspector_comment, s.completed_by, s.completed_at, s.created_at, s.updated_at
FROM _chk_result_snap s
JOIN checklist_items ci ON ci.checklist_code = s.new_code
ON CONFLICT (inspection_id, checklist_item_id) DO NOTHING;

UPDATE findings f
SET checklist_item_id = ci.id,
    checklist_result_id = r.id
FROM _chk_finding_snap s
JOIN checklist_items ci ON ci.checklist_code = s.new_code
LEFT JOIN inspection_checklist_results r
       ON r.inspection_id = s.inspection_id
      AND r.checklist_item_id = ci.id
WHERE f.id = s.finding_id;

UPDATE evidence_files e
SET checklist_item_id = ci.id
FROM _chk_evidence_snap s
JOIN checklist_items ci ON ci.checklist_code = s.new_code
WHERE e.id = s.evidence_id;

-- 7) प्रभावित inspections को completion_percentage र risk_score पुनःगणना
--    (save-item कै सूत्र: checked-na / total_active-na;  risk = high*0.5 + critical*1.0, max 4.0)
UPDATE inspections i
SET completion_percentage = CASE
      WHEN (t.total_active - s.na_count) > 0
        THEN LEAST(100, ROUND((s.checked - s.na_count) * 100.0 / (t.total_active - s.na_count)))
      ELSE 100
    END,
    risk_score = LEAST(4.0, s.high_risk * 0.5 + s.critical_risk * 1.0),
    updated_at = CURRENT_TIMESTAMP
FROM (
    SELECT i2.id AS inspection_id,
           COUNT(CASE WHEN r.compliance_status IS NOT NULL AND r.compliance_status <> 'जाँच बाँकी' THEN 1 END) AS checked,
           COUNT(CASE WHEN r.compliance_status = 'लागू नहुने' THEN 1 END) AS na_count,
           COUNT(CASE WHEN r.risk_level = 'उच्च' THEN 1 END) AS high_risk,
           COUNT(CASE WHEN r.risk_level = 'अत्यन्त उच्च' THEN 1 END) AS critical_risk
    FROM inspections i2
    JOIN inspection_checklist_results r ON r.inspection_id = i2.id
    GROUP BY i2.id
) s
CROSS JOIN (SELECT COUNT(*) AS total_active FROM checklist_items WHERE is_active = TRUE) t
WHERE i.id = s.inspection_id;

-- 8) sequence हरू नयाँ id सँग मिलाउने
SELECT setval(pg_get_serial_sequence('checklist_stages', 'id'), (SELECT COALESCE(MAX(id), 1) FROM checklist_stages), true);
SELECT setval(pg_get_serial_sequence('checklist_items', 'id'), (SELECT COALESCE(MAX(id), 1) FROM checklist_items), true);

COMMIT;
